// Throwaway Swiss-grid layout: can a dense task workspace make focus work clear?
const seed=()=>({page:'focus',tab:'Mission & goals',guide:'Example',step:0,signedIn:true,role:'member',name:'Jordan Hayes',email:'jordan@example.test',emailAlerts:true,status:'Draft',saved:'Not saved this session',objective:'Build and release a clearer next-step screen for one video devotional, using AI to help write code.',notes:'Explore where viewers lose the next step. Keep the experience simple.',gaps:'Viewer needs unclear → Confirm with Product.',personal:'Lead technical design and AI code reviews.',leadership:'',goals:[{goal:'Test 20 viewers; count who find the next step.',target:'20 viewers complete testing; record the baseline.',date:'Month 1',status:'Draft'},{goal:'Release after accessibility and reliability checks.',target:'Complete both checks before releasing to viewers.',date:'Month 3',status:'Draft'},{goal:'Retest 20 viewers; at least 16 find the next step.',target:'At least 16 of 20 viewers identify a next step.',date:'Month 6',status:'Draft'}],comments:[{name:'Casey Morgan · Career lead',text:'Let’s agree the viewer outcome and what evidence will help us review it.'}],memberAgreed:false,leadAgreed:false,history:['Illustrative position focus opened.'],inbox:[{id:1,title:'Draft your position focus',text:'Casey invited you to start a draft for your next conversation. Timing: ask your career lead.',read:false,target:'focus'},{id:2,title:'A note from Casey',text:'Bring your ideas and any gaps to our discussion. This is a simulated notification.',read:false,target:'discussion'},{id:3,title:'Review your current focus',text:'Example reminder only. Agree actual review timing with your career lead.',read:true,target:'discussion'}],members:[{name:'Jordan Hayes',email:'jordan@example.test',role:'Member'},{name:'Casey Morgan',email:'casey@example.test',role:'Career lead'},{name:'Ari Patel',email:'ari@example.test',role:'Member'}],query:''});
let s=seed();const app=document.querySelector('#app'),dialog=document.querySelector('#dialog');const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const btn=(text,action,cls='')=>`<button class="${cls}" data-action="${action}">${text}</button>`;const field=(label,key,value,type='textarea')=>`<label class="field"><span>${label}</span>${type==='input'?`<input data-field="${key}" value="${esc(value)}">`:`<textarea data-field="${key}">${esc(value)}</textarea>`}</label>`;function flash(t){const el=document.querySelector('#toast');el.textContent=t;el.style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.style.display='none',3500)}function state(){const el=document.querySelector('#state');if(el)el.textContent=JSON.stringify(s,null,2)}function go(page,tab){s.page=page;if(tab)s.tab=tab;render();window.scrollTo(0,0)}function log(t){s.history.unshift(t)}function save(){s.saved='Saved in this session';log('Draft saved in memory.');render();flash('Draft saved temporarily. Reloading will reset the demo.')}function tabs(items,current,prefix){return items.map(x=>btn(x,`${prefix}:${x}`,x===current?'active':'')).join('')}
function render(){if(!s.signedIn){app.innerHTML=`<div class="login"><div class="brand">Lantern</div><h1>Welcome back.</h1><p>A clear focus for meaningful work.</p><div class="notice">Prototype sign-in · no real account or Google setup required.</div>${btn('Continue as Jordan Hayes','signin','primary')}<p class="muted">Synthetic account · Engineering department</p></div>`;return}const names={work:'My work',focus:'My position focus',inbox:'Inbox',department:'Engineering department',guide:'A position focus in practice',account:'Account settings'};app.innerHTML=`<aside><div class="brand">Lantern<span class="red">.</span></div><nav>${[['work','☑','My work'],['focus','◎','Position focus'],['inbox','✉','Inbox'],['department','♧','Department'],['guide','▤','Guide'],['account','⚙','Account']].map(([key,icon,label])=>`<button data-action="nav:${key}" class="${s.page===key?'active':''}"><span class="icon">${icon}</span>${label}${key==='inbox'&&s.inbox.some(x=>!x.read)?'<span class="red">●</span>':''}</button>`).join('')}</nav><div class="aside-footer">Engineering<br>04 / Swiss grid<br>Interactive design prototype</div></aside><main><div class="banner"><strong>PROTOTYPE · IN MEMORY</strong><span class="sub">Synthetic content. Reload clears changes.</span>${btn('Reset demo','reset')}</div><header><div><h1>${names[s.page]}</h1><span class="muted">${s.page==='guide'?'Illustrative example · targets are not prescribed':s.page==='focus'?'Clarify your mission and set focused goals.':'Engineering · Jordan Hayes'}</span></div><div class="header-actions">${btn('Inbox '+s.inbox.filter(x=>!x.read).length,'nav:inbox')}<button data-action="nav:account"><span class="avatar">JH</span> <span class="name">${esc(s.name)}</span></button></div></header><div class="content">${({focus:focus,work:work,inbox:inbox,department:department,guide:guide,account:account}[s.page])()}<details class="state"><summary>Prototype state · inspect temporary changes</summary><pre id="state"></pre></details></div></main>`;state()}
function focus(){return `<div class="tabs">${tabs(['Mission & goals','Notes','Gaps & next steps','Development','Discussion','History'],s.tab,'tab')}<div class="right"><span class="status">${s.status}</span>${btn('Save draft','save')}${btn('Discuss with career lead','discuss','primary')}</div></div>${({'Mission & goals':mission,'Notes':()=>`<div class="narrow"><h2>Capture your thinking.</h2><p class="muted">Keep context, questions and observations close to your focus.</p>${field('Working notes','notes',s.notes)}${btn('Save notes','save','primary')}</div>`,'Gaps & next steps':()=>`<div class="narrow"><h2>What needs to become clearer?</h2><div class="flow"><div><i>?</i><span><strong>Gap</strong>What is missing?</span></div><span class="arrow">→</span><div><i>↗</i><span><strong>Next step</strong>Who can help?</span></div></div>${field('Gaps and next steps','gaps',s.gaps)}${btn('Save next steps','save','primary')}</div>`,'Development':development,'Discussion':discussion,'History':()=>`<h2>Your focus can evolve.</h2>${s.history.map((x,i)=>`<div class="list-row"><span class="muted">${String(s.history.length-i).padStart(2,'0')}</span>${esc(x)}</div>`).join('')}`}[s.tab])()}<div class="action-row"><span class="eyebrow">Review timing</span><span class="muted">Ask your career lead.</span>${btn('Open concise guide','nav:guide','text-button')}</div>`}
function mission(){return `<div class="split section"><label class="field"><span>My critical mission objective</span><textarea class="objective" data-field="objective">${esc(s.objective)}</textarea></label><div><h3>How this connects</h3><div class="flow"><div><span><strong>People</strong><small>Who you serve</small></span></div><span class="arrow">→</span><div><span><strong>Outcome</strong><small>What changes</small></span></div><span class="arrow">→</span><div><span><strong>Contribution</strong><small>Why it matters</small></span></div></div>${btn('Help with objectives','help: Objectives'.replace(' ',''),'text-button')}</div></div><div class="row"><h3>SMART goals</h3><span class="muted">Illustrative draft · edit a row to explore</span></div><div class="table-wrap"><table><thead><tr><th>#</th><th style="width:30%">Goal</th><th style="width:27%">Target / success criteria</th><th>Timing</th><th>Status</th><th>Actions</th></tr></thead><tbody>${s.goals.map((g,i)=>`<tr><td>${i+1}</td><td>${esc(g.goal)}</td><td>${esc(g.target)}</td><td>${esc(g.date)}<br><small class="muted">Illustrative</small></td><td><select aria-label="Goal ${i+1} status" data-goal-status="${i}">${['Draft','In progress','Complete'].map(v=>`<option ${v===g.status?'selected':''}>${v}</option>`).join('')}</select></td><td><div class="actions">${btn('Edit',`editgoal:${i}`)}${btn('Delete',`delgoal:${i}`)}</div></td></tr>`).join('')}</tbody></table></div>${btn('＋ Add goal','addgoal')}<div class="triple section" style="margin-top:30px">${field('Notes','notes',s.notes)}${field('Gaps & next steps','gaps',s.gaps)}<div><h3>Development · optional</h3><p>${esc(s.personal)}</p>${btn('Open development →','tab:Development')}</div></div>`}
function development(){return `<h2>Grow through the work.</h2><p class="muted">Optional. Include development when it supports your focus.</p><div class="split">${field('Personal development','personal',s.personal)}${field('Leadership development','leadership',s.leadership)}</div><table><thead><tr><th>Illustrative timing</th><th>Example development goal</th></tr></thead><tbody><tr><td>Month 2</td><td>Compare 2 build options; recommend one to Product.</td></tr><tr><td>Month 6</td><td>Record 3 AI code reviews and fixes.</td></tr></tbody></table>${btn('Save development','save','primary')}`}
function discussion(){return `<div class="split"><div><h2>Discuss. Refine. Agree.</h2><p class="muted">Jordan and Casey work toward a shared position focus.</p>${s.comments.map(c=>`<div class="comment"><strong>${esc(c.name)}</strong><p>${esc(c.text)}</p></div>`).join('')}<label class="field"><span>Add to the discussion</span><textarea id="comment" placeholder="Share a question or suggestion…"></textarea></label>${btn('Post comment','comment','primary')}</div><div><div class="notice"><strong>Joint agreement · simulation</strong><p>Agree after discussing the objective, evidence and timing. You can revise the focus afterwards.</p><p>Jordan: <strong>${s.memberAgreed?'Agreed':'Pending'}</strong><br>Casey: <strong>${s.leadAgreed?'Agreed':'Pending'}</strong></p><div class="action-row">${btn('Agree as Jordan','agreeMember',s.memberAgreed?'':'primary')}${btn('Simulate Casey agreement','agreeLead')}</div>${btn('Revise focus','revise')}</div><h3>Review timing</h3><p>Ask your career lead. No schedule has been set.</p></div></div>`}
function work(){return `<div class="tabs"><strong>YOUR WORKSPACE</strong><span class="right muted">No fixed review schedule</span></div><div class="work-row"><span class="big-num">01</span><div><h2>Shape your position focus</h2><span class="muted">${s.goals.length} goals · ${s.status} · ${s.saved}</span></div>${btn('Continue drafting →','nav:focus','primary')}</div><div class="work-row"><span class="big-num">02</span><div><h2>Prepare for your conversation</h2><span class="muted">Bring context, questions and gaps to Casey.</span></div>${btn('Open discussion →','discussion')}</div><div class="work-row"><span class="big-num">03</span><div><h2>See what good looks like</h2><span class="muted">A concise engineering example, objective beside goals.</span></div>${btn('View example →','example')}</div><div class="split" style="margin-top:30px"><div><h3>Current mission objective</h3><h2>${esc(s.objective)}</h2></div><div><h3>Next conversation</h3><p>Agree timing with your career lead.</p>${btn('Review inbox','nav:inbox','text-button')}</div></div>`}
function inbox(){return `<div class="tabs"><strong>${s.inbox.filter(x=>!x.read).length} UNREAD</strong><div class="right">${btn('Mark all read','readall')}</div></div>${s.inbox.length?s.inbox.map(n=>`<div class="list-row ${!n.read?'unread':''}"><div class="grow"><strong>${esc(n.title)}</strong><p class="muted">${esc(n.text)}</p></div>${btn('Open',`notification:${n.id}`)}${btn(n.read?'Mark unread':'Mark read',`read:${n.id}`)}${btn('Dismiss',`dismiss:${n.id}`)}</div>`).join(''):'<h2>You’re all caught up.</h2>'}<p class="muted">These are sample notifications. No emails or scheduled reminders are sent.</p>`}
function department(){const roster=s.members.filter(m=>(m.name+' '+m.email).toLowerCase().includes(s.query.toLowerCase()));return `<div class="tabs"><strong>${s.members.length} MEMBERS</strong><div class="right"><span class="muted">View as</span><select data-role aria-label="Simulated role"><option value="member" ${s.role==='member'?'selected':''}>Jordan · Member</option><option value="lead" ${s.role==='lead'?'selected':''}>Casey · Career lead</option></select>${s.role==='lead'?btn('Add registered user','addmember','primary'):''}</div></div><p class="muted">${s.role==='member'?'Members can view their department. Switch to Casey above to explore assignment.':'Career-lead assignment simulation. Only eligible registered users can be added.'}</p><input class="search" placeholder="Search department…" aria-label="Search department" id="search" value="${esc(s.query)}"><table><thead><tr><th>Name</th><th>Account</th><th>Role</th><th></th></tr></thead><tbody>${roster.map(m=>`<tr><td>${esc(m.name)}</td><td>${esc(m.email)}</td><td>${m.role}</td><td>${btn('View member',`member:${s.members.indexOf(m)}`)}</td></tr>`).join('')||'<tr><td colspan="4">No matching members.</td></tr>'}</tbody></table>`}
function example(){return `<h3>How this fits together</h3><div class="flow"><div><i>▱</i><span><strong>Screen</strong><small>The next-step experience</small></span></div><span class="arrow">→</span><div><i>♧</i><span><strong>People</strong><small>Viewers find a next step</small></span></div><span class="arrow">→</span><div><i>☆</i><span><strong>Outcome</strong><small>More next steps</small></span></div><span class="arrow">→</span><div><i>▤</i><span><strong>Contribution</strong><small>Engagement with content</small></span></div></div><table class="example"><thead><tr><th>Critical mission objective</th><th colspan="2">SMART goals</th></tr></thead><tbody><tr><td class="mission" rowspan="3">Build and release a clearer next-step screen for one video devotional, using AI to help write code.</td><td>Month 1</td><td>Test 20 viewers; count who find the next step.</td></tr><tr><td>Month 3</td><td>Release after accessibility and reliability checks.</td></tr><tr><td>Month 6</td><td>Retest 20 viewers; at least 16 find the next step.</td></tr></tbody></table><table class="example"><tr><td rowspan="2" style="width:40%"><h3>Personal development · optional</h3>Lead technical design and AI code reviews.</td><td>Month 2</td><td>Compare 2 build options; recommend one to Product.</td></tr><tr><td>Month 6</td><td>Record 3 AI code reviews and fixes.</td></tr></table><table><tr><th style="width:23%">Gaps / next step</th><td>Viewer needs unclear → Confirm with Product.</td></tr></table><p class="muted">Targets are illustrative. Agree review timing with your career lead.</p>${btn('Return to my position focus →','nav:focus','primary')}`}
function guide(){const steps=s.guide==='Objectives'?[['Start with the people','Who should benefit from your work?','Devotional viewers → Find a clear next step'],['Describe the change','Say what should become better, rather than listing activities.','Write code → Help viewers find a next step'],['Connect the contribution','Explain why this outcome matters.','Clear next step → Greater engagement with content']]:[['Make it specific','Choose one outcome and a clear scope.','Improve everything → One video devotional’s next-step screen'],['Make evidence visible','Name what you will measure to learn whether it worked.','Test 20 viewers → Count who find a next step'],['Agree target and timing','Check that the target is achievable and relevant with your career lead.','Month 6: retest 20 → At least 16 find a next step']];const step=steps[s.step];return `<div class="tabs">${tabs(['Objectives','SMART goals','Example'],s.guide,'guide')}</div>${s.guide==='Example'?example():`<div class="steps">${steps.map((x,i)=>`<span class="${i===s.step?'active':''}">${i+1}</span>`).join('')}</div><h2>${step[0]}</h2><p>${step[1]}</p><div class="grid-pair"><div><h3>Starting point</h3><h2>${step[2].split(' → ')[0]}</h2></div><div><h3>A clearer direction →</h3><h2>${step[2].split(' → ')[1]}</h2></div></div><div class="action-row">${btn('← Previous','prevstep')}${btn(s.step===2?'See full example →':'Next →','nextstep','primary')}<span class="muted">${s.step+1} / 3 · A short walkthrough</span></div>${btn('Try this in my draft','nav:focus','text-button')}`}`}
function account(){return `<div class="tabs"><strong>PROFILE & PREFERENCES</strong></div><div class="narrow">${field('Display name','name',s.name,'input')}<label class="field"><span>Email · connected account</span><input readonly value="${esc(s.email)}"></label><div class="split"><div><h3>Department</h3><p>Engineering</p></div><div><h3>Role</h3><p>Member · Career lead: Casey Morgan</p></div></div><label class="check"><input type="checkbox" data-alerts ${s.emailAlerts?'checked':''}>Email notification preference (simulated)</label><div class="action-row">${btn('Save account settings','saveaccount','primary')}${btn('Sign out','signout')}</div><p class="muted">Preferences only change this session. No messages are sent.</p></div>`}
function modal(html){dialog.innerHTML=html;dialog.showModal()}function editGoal(i){let g=i<0?{goal:'',target:'',date:'',status:'Draft'}:s.goals[i];modal(`<h2>${i<0?'Add a SMART goal':'Edit goal '+(i+1)}</h2><form id="goalform" data-index="${i}"><label class="field"><span>Goal</span><textarea name="goal" required>${esc(g.goal)}</textarea></label><label class="field"><span>Success criteria</span><textarea name="target" required>${esc(g.target)}</textarea></label><label class="field"><span>Illustrative timing · agree with career lead</span><input name="date" required value="${esc(g.date)}" placeholder="e.g. Month 1"></label><div class="action-row"><button class="primary" type="submit">${i<0?'Add goal':'Save goal'}</button>${btn('Cancel','close')}</div></form>`)}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;e.preventDefault();const [a,...parts]=b.dataset.action.split(':');const v=parts.join(':');if(a==='nav')go(v);else if(a==='tab'){s.tab=v;render()}else if(a==='guide'||a==='help'){s.page='guide';s.guide=v;s.step=0;render()}else if(a==='example'){s.page='guide';s.guide='Example';render()}else if(a==='save')save();else if(a==='close')dialog.close();else if(a==='reset'){s=seed();dialog.close();render();flash('Demo reset to its starting state.')}else if(a==='signin'){s.signedIn=true;render();flash('Signed in with the synthetic Jordan account.')}else if(a==='signout'){s.signedIn=false;render()}else if(a==='saveaccount'){log('Account preferences saved in memory.');render();flash('Account settings saved for this session.')}else if(a==='discussion')go('focus','Discussion');else if(a==='discuss'){s.status='In discussion';log('Shared for discussion (simulation).');go('focus','Discussion');flash('Discussion opened. Nothing was sent.')}else if(a==='addgoal')editGoal(-1);else if(a==='editgoal')editGoal(Number(v));else if(a==='delgoal')modal(`<h2>Delete this goal?</h2><p>${esc(s.goals[v].goal)}</p><div class="action-row">${btn('Delete goal','confirmdelete:'+v,'primary')}${btn('Keep goal','close')}</div>`);else if(a==='confirmdelete'){s.goals.splice(Number(v),1);dialog.close();log('Goal removed.');render();flash('Goal removed.')}else if(a==='comment'){const t=document.querySelector('#comment').value.trim();if(!t)return flash('Write a comment first.');s.comments.push({name:s.name+' · Member',text:t});log('Discussion comment added.');render();flash('Comment added to the simulated discussion.')}else if(a==='agreeMember'||a==='agreeLead'){if(a==='agreeMember')s.memberAgreed=true;else s.leadAgreed=true;s.status=s.memberAgreed&&s.leadAgreed?'Agreed':'Awaiting agreement';log(a==='agreeMember'?'Jordan agreed.':'Casey agreed (simulation).');render();flash(s.status==='Agreed'?'Both participants have agreed.':'Agreement recorded.')}else if(a==='revise'){s.memberAgreed=false;s.leadAgreed=false;s.status='Draft';log('Focus reopened for revision.');go('focus','Mission & goals');flash('Draft reopened; both agreements cleared.')}else if(a==='readall'){s.inbox.forEach(n=>n.read=true);render();flash('All notifications marked read.')}else if(a==='read'){const n=s.inbox.find(n=>n.id===Number(v));n.read=!n.read;render()}else if(a==='dismiss'){s.inbox=s.inbox.filter(n=>n.id!==Number(v));render();flash('Notification dismissed.')}else if(a==='notification'){const n=s.inbox.find(n=>n.id===Number(v));n.read=true;n.target==='discussion'?go('focus','Discussion'):go('focus','Mission & goals')}else if(a==='prevstep'){s.step=Math.max(0,s.step-1);render()}else if(a==='nextstep'){if(s.step===2)s.guide='Example';else s.step++;render()}else if(a==='member'){const m=s.members[v];modal(`<h2>${esc(m.name)}</h2><p>${esc(m.email)}</p><p>${m.role} · Engineering</p><p class="muted">Only your own draft is accessible in this member prototype.</p><div class="action-row">${s.role==='lead'&&m.role!=='Career lead'?btn('Remove member','removemember:'+v):''}${btn('Close','close')}</div>`)}else if(a==='removemember'){const m=s.members.splice(Number(v),1)[0];dialog.close();render();flash(m.name+' removed from this simulated department.')}else if(a==='addmember'){modal(`<h2>Add a registered user</h2><p>Select an eligible user. This simulates career-lead assignment.</p><label class="field"><span>Registered user</span><select id="newmember"><option value="">Choose a user</option><option value="Sam Rivera" ${s.members.some(m=>m.name==='Sam Rivera')?'disabled':''}>Sam Rivera · ${s.members.some(m=>m.name==='Sam Rivera')?'already assigned':'eligible'}</option><option disabled>Jordan Hayes · already assigned</option><option disabled>Lee Chen · former member</option><option disabled>Morgan Bell · another department</option></select></label><div class="action-row">${btn('Add to Engineering','confirmmember','primary')}${btn('Cancel','close')}</div>`)}else if(a==='confirmmember'){const name=document.querySelector('#newmember').value;if(!name)return flash('Choose an eligible registered user.');s.members.push({name,email:'sam@example.test',role:'Member'});dialog.close();render();flash(name+' added to Engineering.')}});
document.addEventListener('input',e=>{if(e.target.dataset.field){s[e.target.dataset.field]=e.target.value;s.saved='Unsaved changes';state()}if(e.target.id==='search'){s.query=e.target.value;const pos=e.target.selectionStart;render();const el=document.querySelector('#search');el.focus();el.setSelectionRange(pos,pos)}});document.addEventListener('change',e=>{if(e.target.hasAttribute('data-goal-status')){s.goals[Number(e.target.dataset.goalStatus)].status=e.target.value;state();flash('Goal status updated in memory.')}if(e.target.hasAttribute('data-role')){s.role=e.target.value;render();flash('Viewing department as '+(s.role==='lead'?'Casey, career lead.':'Jordan, member.'))}if(e.target.hasAttribute('data-alerts')){s.emailAlerts=e.target.checked;state()}});document.addEventListener('submit',e=>{if(e.target.id!=='goalform')return;e.preventDefault();const f=new FormData(e.target),i=Number(e.target.dataset.index),g={goal:f.get('goal').trim(),target:f.get('target').trim(),date:f.get('date').trim(),status:i<0?'Draft':s.goals[i].status};if(!g.goal||!g.target||!g.date)return flash('Complete the goal, criteria and timing.');if(i<0)s.goals.push(g);else s.goals[i]=g;s.saved='Unsaved changes';log(i<0?'Goal added.':'Goal edited.');dialog.close();render();flash('Goal updated in your temporary draft.');});render();
